sql.where:
AND EXISTS (
    SELECT 1 FROM outlet tenant_outlet
    WHERE tenant_outlet.id = po.outlet_id
      AND tenant_outlet.vendor_id = #{q.vendorId}
      AND tenant_outlet.deleted_at IS NULL
)

AND NOT EXISTS (
    SELECT 1
    FROM shopfront_purchase_order_business_mapping mapped
    JOIN purchase_order canonical ON canonical.id = mapped.purchase_order_id
        AND canonical.outlet_id = mapped.outlet_id
        AND canonical.type = 'ORDER' AND canonical.entered_as = 'SHOPFRONT'
        AND canonical.status = 'RECEIVED'
        AND canonical.reference = mapped.source_id
    WHERE po.type = 'ORDER' AND po.entered_as = 'SHOPFRONT' AND po.status = 'RECEIVED'
      AND mapped.outlet_id = po.outlet_id AND mapped.source_id = po.reference
      AND canonical.id <> po.id AND canonical.invoice_number = po.invoice_number
      AND NOT EXISTS (
          SELECT 1 FROM shopfront_purchase_order_business_mapping own
          WHERE own.outlet_id = po.outlet_id AND own.purchase_order_id = po.id
      )
      AND NOT EXISTS (
          SELECT 1 FROM purchase_receipt receipt
          WHERE receipt.vendor_id = #{q.vendorId} AND receipt.outlet_id = po.outlet_id
            AND receipt.order_id = po.id
      )
      AND NOT EXISTS (
          SELECT 1 FROM purchase_order merged
          WHERE merged.outlet_id = po.outlet_id AND merged.merged_into_id = po.id
      )
)

    AND po.status IN ('OPEN', 'SENT', 'PARTIALLY_RECEIVED')


    AND po.status = #{q.status}


    AND po.type = #{q.type}


    AND po.from_id = #{q.supplierId}


    AND po.to_id = #{q.transferorId}


    AND po.to_id = #{q.outletId}


    AND po.invoice_number LIKE CONCAT('%', #{q.invoiceNumber}, '%')


    AND po.reference LIKE CONCAT('%', #{q.reference}, '%')


    AND po.order_date = #{q.orderDate}


    AND po.order_date >= #{q.orderDateFrom}


    AND po.order_date <= #{q.orderDateTo}


    AND po.due_date = #{q.dueDate}


    AND po.created_by_id = #{q.createdById}


    AND po.sent_by_id = #{q.sentById}


    AND po.received_by_id = #{q.receivedById}


    AND EXISTS (
        SELECT 1 FROM order_product op
        WHERE op.order_id = po.id AND op.product_id = #{q.productId}
    )

mapper.select:

WHERE po.id = #{id}
  AND EXISTS (
      SELECT 1 FROM outlet tenant_outlet
      WHERE tenant_outlet.id = po.outlet_id
        AND tenant_outlet.vendor_id = #{vendorId}
        AND tenant_outlet.deleted_at IS NULL
  )
